var Q17 = [
{n:1, q:'Los delitos contra la administración pública están tipificados en:', o:{a:'El Título XIX del Libro II del Código Penal, que consta de un total de 10 capítulos.',b:'El Título XX del Libro II del Código Penal, que consta de un total de 10 capítulos.',c:'El Título XIX del Libro II del Código Penal, que consta de un total de 9 capítulos.',d:'El Título XX del Libro II del Código Penal, que consta de un total de 9 capítulos.'}, correct:'a', why:{a:'Los delitos contra la Administración Pública están en el Título XIX del Libro II del CP, que consta de 10 capítulos.'}},
{n:2, q:'Dentro del Título XIX del Libro II del Código Penal ¿Qué capítulo lleva por nombre "Del abandono de destino y la omisión del deber de perseguir delitos"?', o:{a:'El capítulo I.',b:'El capítulo II.',c:'El capítulo III.',d:'El capítulo IV.'}, correct:'b', why:{b:'El Capítulo II del Título XIX del CP se denomina "Del abandono de destino y la omisión del deber de perseguir delitos" (arts.407-409).'}},
{n:3, q:'Dentro del Título XIX del Libro II del Código Penal ¿Qué capítulo lleva por nombre "De la infidelidad en la custodia de documentos y de la violación de secretos"?', o:{a:'El capítulo I.',b:'El capítulo II.',c:'El capítulo III.',d:'El capítulo IV.'}, correct:'d', why:{d:'El Capítulo IV del Título XIX del CP se denomina "De la infidelidad en la custodia de documentos y de la violación de secretos" (arts.413-418).'}},
{n:4, q:'Dentro del Título XIX del Libro II del Código Penal ¿Qué capítulo lleva por nombre "De la desobediencia y denegación de auxilio"?', o:{a:'El capítulo I.',b:'El capítulo II.',c:'El capítulo III.',d:'El capítulo IV.'}, correct:'c', why:{c:'El Capítulo III del Título XIX del CP se denomina "De la desobediencia y denegación de auxilio" (arts.410-412).'}},
{n:5, q:'Dentro del Título XIX del Libro II del Código Penal ¿Qué capítulo lleva por nombre "De la prevaricación de los funcionarios públicos y otros comportamientos injustos"?', o:{a:'El capítulo I.',b:'El capítulo II.',c:'El capítulo III.',d:'El capítulo IV.'}, correct:'a', why:{a:'El Capítulo I del Título XIX del CP se denomina "De la prevaricación de los funcionarios públicos y otros comportamientos injustos" (arts.404-406).'}},
{n:6, q:'Dentro del Título XIX del Libro II del Código Penal ¿Qué capítulo lleva por nombre "Del tráfico de influencias"?', o:{a:'El capítulo V.',b:'El capítulo VI.',c:'El capítulo VII.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El Capítulo VI del Título XIX del CP se denomina "Del tráfico de influencias" (arts.428-431).'}},
{n:7, q:'Dentro del Título XIX del Libro II del Código Penal ¿Qué capítulo lleva por nombre "De las negociaciones y actividades prohibidas a los funcionarios públicos y de los abusos en el ejercicio de su función"?', o:{a:'El capítulo V.',b:'El capítulo VI.',c:'El capítulo VII.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'Las negociaciones y actividades prohibidas están en el Capítulo IX del Título XIX (arts.439-444), no en el V, VI ni VII.'}},
{n:8, q:'Dentro del Título XIX del Libro II del Código Penal ¿Qué capítulo lleva por nombre "Del cohecho"?', o:{a:'El capítulo V.',b:'El capítulo VI.',c:'El capítulo VII.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El Capítulo V del Título XIX del CP se denomina "Del cohecho" (arts.419-427).'}},
{n:9, q:'Dentro del Título XIX del Libro II del Código Penal ¿Qué capítulo lleva por nombre "De los fraudes y exacciones ilegales"?', o:{a:'El capítulo VIII.',b:'El capítulo VII.',c:'El capítulo IX.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El Capítulo VIII del Título XIX del CP se denomina "De los fraudes y exacciones ilegales" (arts.436-438).'}},
{n:10, q:'Con respecto al delito de prevaricación del artículo 404 del Código Penal, indique la respuesta incorrecta:', o:{a:'La pena prevista para este delito es la de inhabilitación especial para empleo o cargo público y para el ejercicio del derecho de sufragio pasivo de 9 a 15 años.',b:'Se castiga el hecho de dictar una resolución arbitraria en un asunto administrativo o judicial.',c:'La resolución arbitraria debe dictarse a sabiendas de su injusticia.',d:'Sujeto activo de este delito solo puede serlo una autoridad o funcionario público.'}, correct:'a', why:{a:'La opción a es incorrecta: la pena del art.404 CP es inhabilitación especial para empleo o cargo público de 9 a 15 años (no incluye expresamente el sufragio pasivo; eso es la inhabilitación absoluta).'}},
{n:11, q:'Con respecto al delito de prevaricación (propuestas/nombramientos ilegales) del artículo 405 del Código Penal, indique la respuesta incorrecta:', o:{a:'La pena prevista para este delito es la de inhabilitación especial para empleo o cargo público y para el ejercicio del derecho de sufragio pasivo por tiempo de 9 a 15 años.',b:'Sujeto activo de este delito solo puede ser una autoridad o funcionario público.',c:'La conducta punible consiste de proponer, nombrar o dar posesión para el ejercicio de un determinado cargo público a cualquier persona sin que concurran los requisitos legalmente establecidos para ello.',d:'La propuesta o nombramiento ilegal debe realizarse a sabiendas de su ilegalidad y en el ejercicio de las competencias de quien lo lleva a cabo.'}, correct:'a', why:{a:'La opción a es incorrecta: la pena del art.405 CP es inhabilitación especial para empleo o cargo público de 9 a 15 años, sin que se mencione expresamente el sufragio pasivo como en la inhabilitación absoluta.'}},
{n:12, q:'Con respecto al delito de prevaricación (propuestas/nombramientos ilegales) del artículo 405 del Código Penal, indique la respuesta correcta:', o:{a:'Para que exista delito debe producirse daño para tercero o causa pública.',b:'Si los hechos revisten especial gravedad se impone la pena prevista en su mitad superior.',c:'Para que se consume este delito es preciso que el sujeto activo obtenga algún beneficio, prebenda, dádiva o regalo por su acción.',d:'Este delito se castiga con multa de 3 a 8 meses y suspensión de empleo o cargo público por tiempo de 1 a 3 años.'}, correct:'b', why:{b:'Art.405 CP: si los hechos revisten especial gravedad, la pena se impone en su mitad superior.'}},
{n:13, q:'Julio, en connivencia con el secretario del ayuntamiento de una determinada ciudad, es nombrado agente de la policía local, pese a que no tiene la titulación requerida para optar a esta plaza. Teniendo en cuenta lo anterior, indique la respuesta correcta.', o:{a:'El secretario del ayuntamiento es el único que comete un delito puesto que Julio, aunque es consciente de que carece de titulación, no tiene responsabilidad alguna porque no es funcionario.',b:'Tanto Julián como el Secretario del Ayuntamiento cometen delito.',c:'El secretario del ayuntamiento comete un delito en todo caso. Julio solo cometería delito en el supuesto de que hubiese falsificado la titulación para acceder a la plaza.',d:'Solo Julio sería responsable de un delito.'}, correct:'b', why:{b:'Art.405 CP: tanto el secretario (que propone/da posesión sabiendo la ilegalidad) como Julio (que acepta el nombramiento ilegal conforme al art.406 CP) cometen delito.'}},
{n:14, q:'La persona que acepte la propuesta, nombramiento o toma de posesión para el ejercicio de un determinado cargo público, a sabiendas de que carece de los requisitos legalmente exigibles:', o:{a:'Será castigada con las mismas penas que la autoridad o funcionario público que, a sabiendas, le hubiese dado posesión, propuesto o nombrado.',b:'Será castigada con las penas superiores en grado a las que correspondan a la autoridad o funcionario público que, a sabiendas, le hubiese dado posesión, propuesto o nombrado.',c:'Será castigada con las mismas penas que la autoridad o funcionario público que, a sabiendas, le hubiese dado posesión, propuesto o nombrado, en su mitad superior.',d:'Será castigado con la misma pena de multa que la autoridad o funcionario público que, a sabiendas, le hubiese dado posesión, propuesto o nombrado.'}, correct:'a', why:{a:'Art.406 CP: quien acepta el nombramiento ilegal es castigado con las mismas penas que el funcionario que lo propone o da posesión.'}},
{n:15, q:'En el artículo 407 del Código Penal se castiga con la pena de prisión de 1 a 4 años, e inhabilitación absoluta de 6 a 10 años, a la autoridad o funcionario público que abandonare su destino con el propósito de no impedir o no perseguir cualquiera de los delitos comprendidos:', o:{a:'En los Títulos XX, XXI, XXII y XXIII del Código Penal.',b:'En los Títulos XXI, XXII, XXIII y XXIV del Código Penal.',c:'En los Títulos XX, XXI y XXII del Código Penal.',d:'En los Títulos XX, XXII, XXIII y XXIV del Código Penal.'}, correct:'c', why:{c:'Art.407 CP: el abandono de destino con propósito de no impedir delitos se refiere a los delitos de los Títulos XX (contra la Corona), XXI (contra las instituciones del Estado) y XXII (terrorismo y otros).'}},
{n:16, q:'Según el artículo 407 del Código Penal, cuando la autoridad o funcionario público abandonare su destino con el propósito de no impedir o no perseguir cualquier otro delito del Código Penal que no esté comprendido en los Títulos XXI, XXII, XXIII y XXIV del mismo, incurrirá en la/s pena/s de:', o:{a:'Prisión de 6 meses a 1 año e inhabilitación especial para empleo o cargo público de 1 a 3 años.',b:'Prisión de 6 meses a 1 años e inhabilitación especial para empleo o cargo público de 1 a 3 años.',c:'Multa de 3 a 8 meses e inhabilitación especial para empleo o cargo público de 1 a 3 años.',d:'Inhabilitación especial para empleo o cargo público de 1 a 3 años.'}, correct:'a', why:{a:'Art.407 párr.2 CP: para delitos no incluidos en los Títulos mencionados, la pena es prisión de 6 meses a 1 año e inhabilitación especial para empleo o cargo público de 1 a 3 años.'}},
{n:17, q:'Con respecto al delito de abandono de destino del artículo 407 del Código Penal, indique la respuesta incorrecta:', o:{a:'Sujeto activo solo puede serlo una autoridad o funcionario público.',b:'Las penas a imponer dependen del tipo de delito que no se ha impedido o perseguido como consecuencia del abandono de destino.',c:'También se castiga, con las penas respectivamente previstas, cuando el abandono tenga por objeto no ejecutar las penas impuestas por la autoridad judicial competente.',d:'Se imponen las penas inferiores en uno o dos grados cuando el sujeto que ha llevado a cabo el abandono se reintegre en su destino dentro de las 48 horas siguientes y lleve a cabo los actos necesarios para el impedimento o persecución del delito correspondiente.'}, correct:'d', why:{d:'La opción d es incorrecta: el art.407 CP no prevé una rebaja de pena por reintegración en 48 horas; esa previsión no existe en ese artículo.'}},
{n:18, q:'Con respecto al delito de omisión de perseguir delitos del artículo 408 del Código Penal, indique la respuesta incorrecta:', o:{a:'La conducta delictiva consiste en faltar a la obligación del cargo, dejando intencionadamente de promover la persecución de los delitos de los que se tenga noticia o de sus responsables.',b:'Para que exista delito deben incumplirse resoluciones judiciales u órdenes de la autoridad superior.',c:'Sujeto activo de este delito solo puede serlo una autoridad o funcionario público.',d:'Este delito se castiga con la pena de inhabilitación especial para empleo o cargo público por un tiempo de 6 meses a 2 años.'}, correct:'b', why:{b:'La opción b es incorrecta: el art.408 CP no requiere que se incumplan resoluciones judiciales u órdenes superiores; el delito consiste en no promover la persecución de delitos de los que se tiene noticia, sin necesidad de orden alguna.'}},
{n:19, q:'La autoridad o funcionario público que, faltando a la obligación de su cargo, dejare intencionadamente de promover la persecución de los delitos de que tenga noticia o de sus responsables, será castigado con la pena de:', o:{a:'Inhabilitación absoluta de 6 meses a 2 años.',b:'Prisión de 6 meses a 1 año, e inhabilitación especial para empleo o cargo público de 6 meses a 2 años.',c:'Inhabilitación especial para empleo o cargo público de 6 meses a 2 años.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Art.408 CP: la omisión de perseguir delitos se castiga con inhabilitación especial para empleo o cargo público de 6 meses a 2 años.'}},
{n:20, q:'Con respecto al delito de abandono colectivo y manifiestamente ilegal de un servicio público, el Código Penal castiga con multa y suspensión, a la autoridad o funcionario:', o:{a:'Que lo promoviere.',b:'Que lo dirigiere.',c:'Que lo organizare.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.409 CP: se castiga a quienes promuevan (a), dirijan (b) u organicen (c) el abandono colectivo y manifiestamente ilegal de un servicio público.'}},
{n:21, q:'Con respecto al delito de abandono de un servicio público del artículo 409 del Código Penal, indique la respuesta correcta:', o:{a:'Este precepto solo castiga a quienes dirigieren, promovieren u organizaren tal abandono.',b:'Las autoridades o funcionarios públicos que meramente tomaren parte en el abandono serán castigados con la pena inferior en grado a la prevista para quienes lo dirigieren, promovieren u organizaren.',c:'Si el responsable del abandono fuera autoridad, jefe o responsable de una fuerza pública, o un agente de la autoridad, se impondrán las penas superiores en grado a las respectivamente previstas.',d:'Cuando se trata de dirigentes, promotores u organizadores del abandono de un servicio público se exige que tal abandono sea colectivo y manifiestamente ilegal.'}, correct:'d', why:{d:'Art.409 CP: para que la conducta de los dirigentes, promotores y organizadores sea punible, el abandono debe ser colectivo y manifiestamente ilegal.'}},
{n:22, q:'Con respecto al delito de abandono de un servicio público del artículo 409 del Código Penal, indique la respuesta incorrecta:', o:{a:'Sujeto activo de este delito solo pueden serlo autoridades o funcionarios públicos.',b:'Las autoridades o funcionarios públicos que meramente tomaren parte en el abandono colectivo o manifiestamente ilegal de un servicio público solo cometen este delito cuando el servicio público es esencial y se causa grave perjuicio a éste o a la comunidad.',c:'La pena de multa que tiene señalada este delito es la misma cuando se trata de dirigentes, promotores u organizadores, que cuando se trata de autoridades o funcionarios que meramente han tomado parte en el abandono.',d:'La comisión de este delito, tanto en caso de dirigentes, promotores u organizadores, como en el caso de particulares que meramente tomen parte en dicho abandono, se castiga en todo caso con la pena de suspensión de empleo o cargo público.'}, correct:'c', why:{c:'La opción c es incorrecta: la multa es diferente para dirigentes/organizadores que para quienes simplemente participan; los dirigentes tienen pena de mayor cuantía.'}},
{n:23, q:'Con respecto al delito de desobediencia de autoridades o funcionarios del artículo 410 del Código Penal, indique la respuesta incorrecta:', o:{a:'Solo existe delito cuando se produce una negativa abierta a dar el debido cumplimiento.',b:'La negativa a obedecer debe estar referida a resoluciones judiciales, decisiones u órdenes de la autoridad superior.',c:'Para que tenga lugar este delito las órdenes, decisiones o resoluciones que se desobedecen deben estar dictadas dentro del ámbito de la respectiva competencia de quien las dicta y revestidas de las formalidades legales.',d:'Si el que desobedece es autoridad, jefe o responsable de una fuerza pública o un agente de la autoridad, se impondrán las penas respectivamente previstas en su mitad superior.'}, correct:'a', why:{a:'La opción a es incorrecta: el art.410 CP no exige que la negativa sea "abierta"; basta con la desobediencia, que puede manifestarse de distintas formas.'}},
{n:24, q:'El Código Penal castiga con la pena multa de 3 a 12 meses e inhabilitación especial para empleo o cargo público de 6 meses a 2 años:', o:{a:'A la autoridad o funcionario que se negare abiertamente a dar cumplimiento a resoluciones judiciales dictadas dentro del ámbito de la respectiva competencia y revestidas de las formalidades legales.',b:'A la autoridad o funcionario que se negare abiertamente a dar cumplimiento a decisiones de la autoridad superior, dictadas dentro del ámbito de la respectiva competencia y revestidas de las formalidades legales.',c:'A la autoridad o funcionario que se negare abiertamente a dar cumplimiento a órdenes de la autoridad superior, dictadas dentro del ámbito de la respectiva competencia y revestidas de las formalidades legales.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.410 CP: la pena de multa de 3-12 meses e inhabilitación de 6m-2 años se aplica en todos los supuestos descritos: negativa a resoluciones judiciales (a), decisiones (b) u órdenes de superior (c).'}},
{n:25, q:'Con respecto al delito de desobediencia, el art. 410 del Código Penal dispone que no incurrirá en responsabilidad criminal:', o:{a:'La autoridad o funcionario público que no diere cumplimiento a un mandato que constituya infracción manifiesta, clara y terminante de un precepto de Ley.',b:'La autoridad o funcionario público que no diere cumplimiento a un mandato en el que se infrinja, de manera manifiesta, clara y terminante cualquier disposición general.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.410.2 CP: no incurre en responsabilidad quien no cumple un mandato que constituya infracción manifiesta, clara y terminante de un precepto de Ley (a). La b menciona "cualquier disposición general", lo que es una redacción distinta y más amplia que no coincide exactamente con el texto legal.'}},
{n:26, q:'En el artículo 411 del Código Penal se castiga a la autoridad o funcionario público que habiendo suspendido la ejecución de las órdenes de sus superiores, las desobedeciere después de que aquéllos hubieren desaprobado la suspensión. Sin embargo, como excepción, no incurrirán en responsabilidad:', o:{a:'Aquellos que den cumplimiento a un mandato que constituya una infracción manifiesta, clara y terminante de un precepto de ley.',b:'Quienes hubieren advertido, previamente y por escrito, al superior de quien emana la orden de la presunta legalidad de la misma, y se hallen en espera de respuesta.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.411 CP: no incurren en responsabilidad quienes cumplen mandato que es infracción manifiesta de ley (a) ni quienes han advertido por escrito sobre su ilegalidad y esperan respuesta (b).'}},
{n:27, q:'En el artículo 411 del Código Penal se castiga a la autoridad o funcionario público que habiendo suspendido la ejecución de las órdenes de sus superiores, las desobedeciere después de que aquéllos hubieren desaprobado la suspensión. Sin embargo, como excepción, este precepto dispone que no incurrirán en responsabilidad...', o:{a:'Aquellos que hubiesen actuado por imprudencia menos grave.',b:'Aquellos que no den cumplimiento a un mandato que constituya una infracción manifiesta, clara y terminante de cualquier disposición general.',c:'Aquellos que no den cumplimiento a un mandato que constituya una infracción manifiesta, clara y terminante de cualquier acto administrativo.',d:'Las respuestas b y c son correctas.'}, correct:'b', why:{b:'Art.411 CP: tampoco incurren en responsabilidad quienes no dan cumplimiento a un mandato que constituya infracción manifiesta de cualquier disposición general.'}},
{n:28, q:'La suspensión o desobediencia reiterada de una orden por parte de autoridad o funcionario público, será castigada con la pena de:', o:{a:'Multa de 12 a 24 meses e inhabilitación especial para empleo o cargo público de 1 a 3 años.',b:'Multa de 12 a 18 meses e inhabilitación especial para empleo o cargo público de 1 a 3 años.',c:'Multa de 12 a 24 meses e inhabilitación especial para empleo o cargo público de 1 a 2 años.',d:'Multa de 12 a 18 meses e inhabilitación especial para empleo o cargo público de 1 a 2 años.'}, correct:'a', why:{a:'Art.411 CP: la suspensión o desobediencia reiterada se castiga con multa de 12 a 24 meses e inhabilitación especial para empleo o cargo público de 1 a 3 años.'}},
{n:29, q:'Con respecto al delito de denegación de auxilio por parte de autoridad o funcionario, el artículo 412 del Código Penal castiga:', o:{a:'La denegación de auxilio a la Administración de Justicia u otro servicio público.',b:'La denegación de auxilio a un particular.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.412 CP: se castiga tanto la denegación de auxilio a la Administración de Justicia u otro servicio público (a) como a los particulares (b).'}},
{n:30, q:'El funcionario que, requerido por autoridad competente, no prestare el auxilio debido a la Administración de Justicia u otro servicio público, será castigado con pena de:', o:{a:'Multa de 3 a 12 meses y suspensión de empleo o cargo público de 6 meses a 2 años.',b:'Multa de 12 a 18 meses e inhabilitación especial para empleo o cargo público de 1 a 2 años.',c:'Multa de 6 a 12 meses y suspensión de empleo o cargo público de 6 meses a 3 años.',d:'Multa de 12 a 18 meses e inhabilitación especial para empleo o cargo público de 1 a 3 años.'}, correct:'a', why:{a:'Art.412.1 CP: el funcionario que no presta auxilio a la Administración de Justicia u otro servicio público se castiga con multa de 3 a 12 meses y suspensión de empleo o cargo público de 6 meses a 2 años.'}},
{n:31, q:'La autoridad o funcionario que se abstuviera de prestar el auxilio solicitado por un particular para evitar un delito contra la vida de las personas, será castigado con la pena de:', o:{a:'Multa de 3 a 12 meses y suspensión de empleo o cargo público de 6 meses a 2 años.',b:'Multa de 18 a 24 meses e inhabilitación especial para empleo o cargo público de 3 a 6 años.',c:'Multa de 6 a 12 meses y suspensión de empleo o cargo público de 6 meses a 3 años.',d:'Multa de 12 a 18 meses e inhabilitación especial para empleo o cargo público de 1 a 3 años.'}, correct:'b', why:{b:'Art.412.3 CP: no prestar auxilio solicitado para evitar un delito contra la vida se castiga con multa de 18 a 24 meses e inhabilitación especial para empleo o cargo público de 3 a 6 años.'}},
{n:32, q:'Se imponen penas de mayor gravedad a las contenidas en el tipo básico, cuando el responsable fuere autoridad, jefe o responsable de una fuerza pública. Esta afirmación es aplicable al delito de...', o:{a:'Denegación de auxilio a la justicia del artículo 412.1 del Código Penal.',b:'Desobediencia del artículo 410.1 del Código Penal.',c:'Denegación de auxilio a particulares del artículo 412.3 del Código Penal.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Arts.410.2, 412.2 y 412.3 CP: en todos esos delitos, cuando el responsable es autoridad, jefe o responsable de fuerza pública, se imponen penas superiores.'}},
{n:33, q:'Con respecto al delito de denegación de auxilio a particulares del artículo 412.3 del Código Penal, indique la respuesta correcta:', o:{a:'Para que exista delito se exige que la autoridad o funcionario requerido venga obligado a evitar el delito por razón de su cargo.',b:'La gravedad de la pena a imponer depende del tipo de delito cuyo auxilio se hubiese denegado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.412.3 CP: se requiere obligación de evitar el delito por razón del cargo (a) y la pena varía según el tipo de delito cuyo auxilio se deniega (b).'}},
{n:34, q:'El delito de denegación de auxilio a particulares, previsto en el artículo 412.3 del Código Penal se castiga con la pena de multa de 12 a 18 meses y suspensión de empleo o cargo público de 1 a 3 años, cuando el delito por el que se efectuó el requerimiento:', o:{a:'Es un delito contra la libertad de las personas.',b:'Es un delito contra la vida de las personas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.412.3 párr.1 CP: la pena de multa 12-18 meses y suspensión 1-3 años se aplica cuando el delito cuyo auxilio se deniega es contra la libertad de las personas.'}},
{n:35, q:'El delito de denegación de auxilio a particulares, previsto en el artículo 412.3 del Código Penal se castiga con la pena de multa de 12 a 18 meses y suspensión de empleo o cargo público de 1 a 3 años, cuando el delito por el que se efectuó el requerimiento:', o:{a:'Es un delito contra la salud de las personas.',b:'Es un delito contra la libertad sexual de las personas.',c:'Es un delito contra la integridad de las personas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.412.3 CP: la misma pena se aplica cuando el delito cuyo auxilio se deniega es contra la salud (a), la libertad sexual (b) o la integridad (c) de las personas.'}},
{n:36, q:'En el delito de denegación de auxilio a particulares, previsto en el artículo 412.3 del Código Penal, cuando el requerimiento realizado lo fuere para cualquier delito o mal que no constituyera delito contra la vida, la salud, la integridad, la libertad sexual o la libertad de las personas, la pena a imponer será:', o:{a:'Multa de 3 a 12 meses y suspensión de empleo o cargo público de 6 meses a 2 años.',b:'Multa de 18 a 24 meses e inhabilitación especial para empleo o cargo público de 3 a 6 años.',c:'Multa de 6 a 12 meses y suspensión de empleo o cargo público de 6 meses a 3 años.',d:'Multa de 12 a 18 meses e inhabilitación especial para empleo o cargo público de 1 a 3 años.'}, correct:'d', why:{d:'Art.412.3 párr.2 CP: cuando el requerimiento es para un delito distinto de los principales, la pena es multa de 12 a 18 meses e inhabilitación especial de 1 a 3 años.'}},
{n:37, q:'Con respecto al delito de infidelidad en la custodia de documentos del artículo 413 del Código Penal, indique la respuesta incorrecta.', o:{a:'Sujeto activo de este delito solo pueden serlo las autoridades o funcionarios públicos.',b:'Para que exista delito, las conductas que se indican deben llevarse a cabo "a sabiendas".',c:'Cuando se trata de destrucción o inutilización de documentos solo existe delito si dichos documentos han quedado totalmente destruidos.',d:'Ocultar los documentos se castiga con las mismas penas que si se produjere la destrucción de los mismos.'}, correct:'c', why:{c:'La opción c es incorrecta: el art.413 CP no exige que la destrucción sea total; basta con cualquier acto de destrucción o inutilización de los documentos.'}},
{n:38, q:'Con respecto al delito de infidelidad en la custodia de documentos del artículo 413 del Código Penal, indique la respuesta correcta.', o:{a:'Para que exista delito se exige que el autor de los hechos tenga encomendada la custodia de los documentos por razón de su cargo.',b:'Este delito puede ser cometido tanto por autoridad o funcionario público, como por particulares.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.413 CP: requiere que el autor tenga encomendada la custodia por razón del cargo (a), y puede ser cometido tanto por funcionarios como por particulares (b).'}},
{n:39, q:'En el delito de infidelidad en la custodia de documentos de acceso restringido del artículo 414 del Código Penal, la conducta típica consiste en:', o:{a:'Destruir o inutilizar los medios puestos para restringir el acceso a esos documentos.',b:'Sustraer, inutilizar u ocultar los documentos cuya custodia le haya sido encomendada.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.414 CP: la conducta del delito de infidelidad en custodia de documentos de acceso restringido consiste en destruir o inutilizar los medios puestos para restringir el acceso.'}},
{n:40, q:'En el delito de infidelidad en la custodia de documentos de acceso restringido del artículo 414 del Código Penal, la conducta típica consiste en:', o:{a:'Destruir o inutilizar los medios puestos para restringir el acceso a esos documentos.',b:'Consentir la destrucción o inutilización de los medios puestos para restringir el acceso a esos documentos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.414 CP: tanto destruir/inutilizar (a) como consentir la destrucción/inutilización (b) de los medios de restricción son conductas típicas.'}},
{n:41, q:'En el delito de infidelidad en la custodia de documentos de acceso restringido del artículo 414 del Código Penal, el sujeto activo:', o:{a:'Solo puede ser autoridad o funcionario público.',b:'Puede ser autoridad, funcionario público o particular.',c:'Solo puede ser autoridad o funcionario público en el ejercicio de sus funciones.',d:'Sólo puede ser autoridad o funcionario público que, por razón de su cargo, tenga encomendada la custodia de esos documentos.'}, correct:'d', why:{d:'Art.414 CP: el sujeto activo debe ser autoridad o funcionario público que tenga encomendada la custodia de esos documentos por razón de su cargo.'}},
{n:42, q:'El delito de infidelidad en la custodia de documentos del artículo 414 del Código Penal se castiga con la pena de multa de 6 a 18 meses...', o:{a:'Cuando fuere cometido por imprudencia grave.',b:'Cuando fuere de menor gravedad en atención al medio empleado o al resultado producido.',c:'Cuando no se obtuviere el beneficio perseguido.',d:'Cuando fuere cometido por un particular.'}, correct:'b', why:{b:'Art.414 CP: la pena se reduce a multa de 6 a 18 meses cuando el delito es de menor gravedad atendiendo al medio empleado o al resultado.'}},
{n:43, q:'Con respecto al delito de infidelidad en la custodia de documentos del artículo 415 del Código Penal, indique la respuesta incorrecta:', o:{a:'La conducta típica consiste en acceder o permitir el acceso a documentos secretos.',b:'Para que exista delito el sujeto activo debe obrar a sabiendas y sin la debida autorización.',c:'Para que exista delito los documentos a los que se hace referencia deben estar confiados al sujeto activo por razón de su cargo.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'d', why:{d:'Las opciones a, b y c son todas correctas respecto al art.415 CP, por lo que la respuesta incorrecta sería d ("todas incorrectas"), que en realidad es incorrecta como afirmación.'}},
{n:44, q:'En el artículo 416 del Código Penal se castiga la infidelidad en la custodia de documentos, en todas sus modalidades, cometida por particulares que estén encargados accidentalmente del despacho o custodia de documentos...', o:{a:'Por comisión del gobierno.',b:'Por comisión de autoridades o funcionarios públicos a quienes hayan sido confiados por razón de su cargo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.416 CP: los particulares que por comisión de autoridades o funcionarios estén accidentalmente encargados de documentos pueden ser sujetos activos de este delito.'}},
{n:45, q:'Con respecto al delito de revelación de secretos del artículo 417 del Código Penal, indique la respuesta incorrecta:', o:{a:'Sujeto activo de este delito solo pueden serlo los funcionarios públicos o autoridades.',b:'La conducta típica consiste en revelar secretos o informaciones de los que se tenga conocimiento por razón del oficio o cargo y no deban ser divulgados.',c:'Si de la revelación resulta grave daño para la causa pública o para tercero se impondrán las penas previstas en su mitad superior.',d:'Si se revelan secretos de un particular se imponen penas de mayor gravedad.'}, correct:'d', why:{d:'La opción d es incorrecta: el art.417 CP no prevé penas mayores específicamente por revelar secretos de un particular; la distinción se hace por el daño a la causa pública o a tercero.'}},
{n:46, q:'Con respecto al delito de revelación de secretos del artículo 417 del Código Penal, indique la respuesta correcta:', o:{a:'El tipo básico se castiga con multa de 12 a 18 meses y suspensión de empleo o cargo público por tiempo de 1 a 3 años.',b:'Si resultara grave daño para la causa pública se impondrá la pena de prisión de 1 a 3 años e inhabilitación especial para empleo o cargo público de 3 a 5 años.',c:'Si se revelan los secretos de un particular se impondrán las penas de prisión de 2 a 5 años, multa de 12 a 18 meses, y suspensión de empleo o cargo público de 1 a 3 años.',d:'Si resultara grave daño para tercero se impondrá la pena de prisión de 1 a 3 años e inhabilitación especial para empleo o cargo público de 2 a 4 años.'}, correct:'a', why:{a:'Art.417.1 CP: el tipo básico de revelación de secretos por funcionario se castiga con multa de 12 a 18 meses y suspensión de empleo o cargo público de 1 a 3 años.'}},
{n:47, q:'Con respecto al delito de violación de secretos del artículo 418 del Código Penal, indique la respuesta incorrecta:', o:{a:'Sujeto activo de este delito solo pueden serlo los funcionarios públicos o autoridades.',b:'La conducta típica consiste en aprovechar para sí o para un tercero el secreto o la información privilegiada que se obtuviere de un funcionario público o autoridad.',c:'Este delito se castiga con la pena de multa del tanto al triplo del beneficio obtenido o facilitado y la pérdida de la posibilidad de obtener subvenciones, y del derecho a gozar de beneficios o incentivos fiscales o de la seguridad social durante un periodo de 1 a 3 años.',d:'Si resultare grave daño para la causa pública o para tercero, la pena será de prisión de 1 a 6 años y la pérdida de la posibilidad de obtener subvenciones o del derecho a gozar de beneficios o incentivos fiscales o de la seguridad social durante un periodo de 6 a 10 años.'}, correct:'a', why:{a:'La opción a es incorrecta: el art.418 CP puede ser cometido por cualquier persona, no solo funcionarios o autoridades. El sujeto activo en este delito puede ser un particular.'}},
{n:48, q:'En el artículo 418 del Código Penal se castiga al particular que aprovechare para sí o para un tercero el secreto o la información privilegiada obtenida de un funcionario público o autoridad. En estos casos, el particular será castigado con pena de prisión si...', o:{a:'Resultare grave daño para tercero o causa pública.',b:'Obtuviere el beneficio perseguido.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.418 CP: la pena de prisión se aplica cuando resulta grave daño para tercero o causa pública (a). Si solo se obtiene beneficio sin grave daño, la pena es menor.'}},
{n:49, q:'Con respecto al delito de cohecho pasivo propio del artículo 419 del Código Penal, indique la respuesta incorrecta.', o:{a:'Sujeto activo de este delito solo pueden serlo las autoridades y funcionarios públicos.',b:'Se requiere que la conducta típica se realice en beneficio propio o de un tercero.',c:'El delito puede cometerse también por medio de persona interpuesta.',d:'Las penas previstas se imponen en su mitad superior si resultare grave daño para tercero o causa pública.'}, correct:'d', why:{d:'La opción d es incorrecta: el art.419 CP no prevé que las penas se impongan en su mitad superior cuando resulta grave daño; esa previsión específica no está en ese artículo.'}},
{n:50, q:'Recibir o solicitar dádiva, favor o retribución de cualquier clase, o aceptar ofrecimiento o promesa para realizar, en el ejercicio del cargo, un acto contrario a los deberes inherentes al mismo es una conducta que integra el delito de:', o:{a:'Cohecho del artículo 419 del Código Penal.',b:'Cohecho del artículo 420 del Código Penal.',c:'Cohecho del artículo 421 del Código Penal.',d:'Cohecho del artículo 422 del Código Penal.'}, correct:'a', why:{a:'Art.419 CP: recibir/solicitar dádiva para realizar un acto contrario a los deberes inherentes al cargo es el cohecho pasivo propio del art.419 CP.'}},
{n:51, q:'Recibir o solicitar dádiva, favor o retribución de cualquier clase, o aceptar ofrecimiento o promesa para no realizar o retrasar injustificadamente un acto que se debiera practicar en el ejercicio del cargo, es una conducta que integra el delito de:', o:{a:'Cohecho del artículo 419 del Código Penal.',b:'Cohecho del artículo 420 del Código Penal.',c:'Cohecho del artículo 421 del Código Penal.',d:'Cohecho del artículo 422 del Código Penal.'}, correct:'b', why:{b:'Art.420 CP: recibir/solicitar dádiva para no realizar o retrasar injustificadamente un acto que se debería practicar es el cohecho pasivo del art.420 CP.'}},
{n:52, q:'Con respecto al delito de cohecho del artículo 419 del Código Penal, indique la respuesta incorrecta:', o:{a:'Sujetos activos de este delito solo pueden serlo las autoridades y funcionarios públicos.',b:'Para que exista delito la conducta debe realizarse en provecho propio o de tercero.',c:'Se castiga a quien recibiere o solicitare dádiva, favor o retribución de cualquier clase y también a quien aceptare ofrecimiento o promesa para no realizar o retrasar injustificadamente el acto que debiera realizar.',d:'Este delito se castiga con las penas de prisión de 3 a 6 años, multa de 12 a 18 meses e inhabilitación especial para empleo o cargo público y para el ejercicio del derecho de sufragio pasivo de 9 a 12 años.'}, correct:'c', why:{c:'La opción c es incorrecta: describe simultáneamente las conductas del art.419 (acto contrario a deberes) y del art.420 (no realizar o retrasar). El art.419 solo castiga realizar acto contrario a deberes.'}},
{n:53, q:'Con respecto al delito de cohecho del artículo 420 del Código Penal, indique la respuesta incorrecta:', o:{a:'Sujetos activos de este delito solo pueden serlo las autoridades y funcionarios público.',b:'Para que exista delito la conducta debe realizarse en provecho propio o de tercero.',c:'Se castiga a quien recibiere o solicitare dádiva, favor o retribución de cualquier clase y también a quien aceptare ofrecimiento o promesa para no realizar o retrasar injustificadamente el acto que debiera practicar.',d:'Este delito se castiga con prisión de 2 a 4 años, multa de 12 a 24 meses e inhabilitación especial para empleo o cargo público y para el ejercicio del derecho de sufragio pasivo por tiempo de 5 a 9 años.'}, correct:'d', why:{d:'La opción d es incorrecta: la pena del art.420 CP es prisión de 2 a 4 años, multa de 12 a 24 meses e inhabilitación especial para empleo/cargo público y sufragio pasivo de 3 a 7 años (no 5 a 9).'}},
{n:54, q:'Manuel, funcionario público adscrito al Departamento de Urbanismo de un determinado Ayuntamiento, es recompensado con tres mil euros por haber tramitado una licencia para la construcción de un hotel. En la tramitación se ha seguido el procedimiento legal y reglamentariamente establecido. Teniendo en cuenta lo descrito, indique la respuesta correcta.', o:{a:'Manuel no comete delito alguno.',b:'Manuel podría ser considerado autor de un delito de cohecho previsto y penado en el artículo 419 del Código Penal.',c:'Manuel podría ser considerado autor de un delito de cohecho previsto y penado en el artículo 420 del Código Penal.',d:'Manuel podría ser considerado autor de un delito de cohecho previsto y penado en el artículo 421 del Código Penal.'}, correct:'d', why:{d:'Art.422 CP (cohecho pasivo subsiguiente): Manuel ha recibido una recompensa por un acto ya realizado, que además era legal. Esto corresponde al cohecho pasivo subsiguiente o de recompensa. El libro señala art.421, que es el cohecho por actos propios del cargo.'}},
{n:55, q:'El cohecho pasivo subsiguiente o de recompensa...', o:{a:'Se castiga en el artículo 422 del Código Penal.',b:'Consiste en recibir o solicitar dádiva, favor o retribución, por parte de autoridad o funcionario público, como recompensa por la actividad realizada.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.422 CP: el cohecho pasivo subsiguiente o de recompensa (a) consiste en recibir/solicitar dádiva como recompensa por la actividad realizada (b).'}},
{n:56, q:'En el artículo 422 del Código Penal se castiga a la autoridad o funcionario público que, en provecho propio o de un tercero, admitiera, por sí o por persona interpuesta, dádiva o regalo:', o:{a:'Que le fueren ofrecidos como recompensa por haber realizado un acto propio de su cargo.',b:'Que le fueren ofrecidos en consideración a su cargo o función.',c:'Que le fueren ofrecidos para no realizar o retrasar injustificadamente un acto propio de su cargo que debiera practicar.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.422 CP: se castiga al funcionario que admite dádivas ofrecidas como recompensa por actos propios del cargo (a), en consideración a su cargo (b) o para omitir actos debidos (c).'}},
{n:57, q:'En el artículo 420 del Código Penal se castiga a la autoridad o funcionario público que, en provecho propio o de un tercero, recibiera, por sí o por persona interpuesta, dádiva, favor o retribución de cualquier clase:', o:{a:'Para realizar un acto propio de su cargo.',b:'Que le fueren ofrecidos en consideración a su cargo o función.',c:'Que le fueren ofrecidos para no realizar o retrasar injustificadamente un acto propio de su cargo que debiera practicar.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'Art.420 CP: se castiga al funcionario que recibe dádiva para no realizar o retrasar injustificadamente un acto que debería practicar.'}},
{n:58, q:'De acuerdo con lo previsto en el artículo 423 del Código Penal, a los jurados, árbitros, peritos, administradores o interventores designados judicialmente, les son de aplicación, en sus respectivos casos, los delitos de cohecho previstos en:', o:{a:'Los artículos 419 y 420 del Código Penal.',b:'Los artículos 421 y 422 del Código Penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.423 CP: a jurados, árbitros, peritos e interventores designados judicialmente les son de aplicación los delitos de cohecho de los arts.419-422 CP.'}},
{n:59, q:'En nuestro Código Penal, los delitos de cohecho activo se regulan en:', o:{a:'Los artículos 424 y 425 del Código Penal.',b:'Los artículos 421 y 422 del Código Penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Arts.424 y 425 CP: los delitos de cohecho activo (el que ofrece o entrega la dádiva) están en los artículos 424 y 425 del CP.'}},
{n:60, q:'Con respecto al delito de cohecho activo del artículo 424.1 del Código Penal, indique la respuesta incorrecta.', o:{a:'Sujeto activo de éste delito solo pueden serlo las autoridades o funcionarios públicos.',b:'Se castiga con la pena de prisión de 6 meses a 1 año o multa de 12 a 24 meses.',c:'Se impondrán las penas previstas en su mitad superior cuando el hecho derivare grave perjuicio para el interés público o causa pública.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'La opción a es incorrecta: el cohecho activo del art.424 CP puede ser cometido por cualquier persona, no solo autoridades o funcionarios.'}},
{n:61, q:'Constituye delito de cohecho del artículo 424.1 del Código Penal:', o:{a:'Ofrecer o entregar dádiva o retribución de cualquier clase a una autoridad, funcionario público, o persona que participe en el ejercicio de la función pública, para que realice un acto contrario a los deberes inherentes a su cargo.',b:'Ofrecer o entregar dádiva o retribución de cualquier clase a una autoridad, funcionario público, o a cualquier persona que participe en el ejercicio de la función pública, para que no realice o retrase un acto que debiera practicar.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.424.1 CP: el cohecho activo consiste en ofrecer/entregar dádiva para que el funcionario realice un acto contrario a sus deberes (a). La conducta de la opción b corresponde al art.424.2.'}},
{n:62, q:'En el delito de cohecho del artículo 424.2 del Código Penal se castiga al particular que:', o:{a:'Ofreciere o entregare dádiva o retribución de cualquier clase a una autoridad, funcionario público o persona que participe en el ejercicio de la función pública para que no realice o retrase un acto que debiera practicar.',b:'Entregare dádiva o retribución atendiendo a la solicitud de la autoridad, funcionario público o persona que participe en el ejercicio de la función pública.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.424.2 CP: tanto ofrecer/entregar dádiva para que el funcionario no actúe o retrase (a) como entregar atendiendo la solicitud del funcionario (b) constituyen cohecho activo.'}},
{n:63, q:'Cuando el soborno tenga lugar en causa criminal a favor del reo, se produce una atenuación de la pena, siempre y cuando:', o:{a:'El sujeto activo sea cónyuge del reo o persona ligada a éste por análoga relación de afectividad.',b:'El sujeto activo sea ascendiente, descendiente o hermano del reo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.425 CP: la atenuación de la pena cuando el soborno es en causa criminal a favor del reo opera cuando el sujeto activo es cónyuge/pareja (a) o ascendiente/descendiente/hermano (b).'}},
{n:64, q:'Tiene/n la consideración de sujeto activo en el delito de soborno en causa criminal a favor del reo del artículo 425 del Código Penal:', o:{a:'El cónyuge o persona que se halle ligada al reo por análoga relación de afectividad.',b:'Las autoridades y funcionarios públicos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.425 CP: el sujeto activo en el soborno en causa criminal a favor del reo son el cónyuge/pareja (a) y los familiares del reo, no las autoridades o funcionarios (b).'}},
{n:65, q:'Tiene/n la consideración de sujeto activo del delito de soborno en causa criminal a favor del reo del artículo 425 del Código Penal:', o:{a:'Ascendientes y descendientes del reo.',b:'Hermanos del reo por naturaleza, por adopción o afines en los mismos grados.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.425 CP: ascendientes/descendientes (a) y hermanos (b) también tienen consideración de sujeto activo atenuado en el soborno a favor del reo.'}},
{n:66, q:'La excusa absolutoria del artículo 426 del Código Penal solo es aplicable a los delitos de:', o:{a:'Cohecho.',b:'Tráfico de influencias.',c:'Malversación.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'Art.426 CP: la excusa absolutoria (para quien denuncia el cohecho antes de la apertura del procedimiento) solo es aplicable a los delitos de cohecho.'}},
{n:67, q:'El particular que haya accedido ocasionalmente a la solicitud de dádiva u otra retribución realizada por autoridad o funcionario público y denuncie el hecho a la autoridad que tenga el deber de proceder a su averiguación quedará exento de pena por el delito de cohecho:', o:{a:'Siempre que lo denuncie antes de la apertura del procedimiento y no hayan transcurrido más de tres meses desde la fecha de los hechos.',b:'Siempre que lo denuncie antes de la apertura del procedimiento y no hayan transcurrido más de dos meses desde la fecha de los hechos.',c:'Siempre que lo denuncie antes de la apertura del juicio oral y no hayan transcurrido más de tres meses desde la fecha de los hechos.',d:'Siempre que lo denuncie antes de la apertura del juicio oral y no hayan transcurrido más de dos meses desde la fecha de los hechos.'}, correct:'a', why:{a:'Art.426 CP: la excusa absolutoria requiere denuncia antes de la apertura del procedimiento y que no hayan transcurrido más de tres meses desde los hechos.'}},
{n:68, q:'Según lo dispuesto en el artículo 427 del Código Penal, lo dispuesto en los artículos 419 a 426 de este Código será también aplicable cuando las conductas descritas sean realizadas por o afecten a...', o:{a:'Agente de cualquier organización internacional pública.',b:'Cualquier persona que ejerza una función pública para un país de la Unión Europea.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.427 CP: los delitos de cohecho se aplican también a agentes de organizaciones internacionales (a) y a quienes ejercen función pública en la UE (b).'}},
{n:69, q:'Según lo dispuesto en el artículo 427 del Código Penal, lo dispuesto en los artículos 419 a 426 de este Código será también aplicable cuando las conductas descritas sean realizadas por o afecten a...', o:{a:'Cualquier persona que ostente un cargo o empleo legislativo en un país extranjero.',b:'Cualquier persona que ejerza una función pública para un organismo público.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.427 CP: también aplica a quienes ostentan cargo legislativo extranjero (a) y a quienes ejercen función pública en organismo público (b).'}},
{n:70, q:'Según lo dispuesto en el artículo 427 del Código Penal, lo dispuesto en los artículos 419 a 426 de este Código será también aplicable cuando las conductas descritas sean realizadas por o afecten a...', o:{a:'Cualquier persona que realice funciones o preste servicios para empresas o entidades privadas, que hayan recibido asignaciones con cargo a los fondos públicos en los últimos cuatro años.',b:'Cualquier funcionario de la Unión Europea.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.427 CP: los delitos de cohecho también aplican a cualquier funcionario de la Unión Europea (b). La opción a (empresas privadas con fondos públicos) no está en el art.427.'}},
{n:71, q:'Según lo dispuesto en el artículo 427 del Código Penal, lo dispuesto en los artículos 419 a 426 de este Código será también aplicable cuando las conductas descritas sean realizadas por o afecten a...', o:{a:'Cualquier persona que ostente un cargo o empleo legislativo de un país de la Unión Europea.',b:'Cualquier persona que ostente un cargo judicial de cualquier país extranjero.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.427 CP: aplica también a quienes ostentan cargo legislativo en la UE (a) y a quienes ostentan cargo judicial extranjero (b).'}},
{n:72, q:'Según lo dispuesto en el artículo 427 del Código Penal, lo dispuesto en los artículos 419 a 426 de este Código será también aplicable cuando las conductas descritas sean realizadas por o afecten a...', o:{a:'Cualquier persona a la que se haya asignado y esté ejerciendo una función de servicio público que consista en la gestión de intereses financieros de la Unión Europea.',b:'Cualquier persona que ejerza funciones de abogacía o procuraduría en el ámbito de la Unión Europea.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.427 CP: aplica también a quienes gestionan intereses financieros de la UE (a). El ejercicio de abogacía en la UE (b) no está expresamente en el art.427.'}},
{n:73, q:'Cuando una persona jurídica sea responsable de alguno de los delitos contenidos en el capítulo V, del Título XIX, del Libro II del Código Penal, será castigada.', o:{a:'Con multa de uno a dos años, o del doble al triplo del beneficio obtenido cuando la cantidad resultante fuese más elevada, si el delito cometido por la persona física tiene prevista una pena de más de dos años, y hasta cinco años, de privación de libertad.',b:'Con multa de cinco años, o del triple al quíntuple del beneficio obtenido cuando la cantidad resultante fuese más elevada, si el delito cometido por la persona física tiene prevista una pena de prisión de más de cinco años.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.427 bis CP: la persona jurídica se castiga con multa de 1-2 años o doble-triple beneficio (delitos con pena persona física >2 y hasta 5 años) (a) y multa de 5 años o triple-quíntuple (>5 años) (b).'}},
{n:74, q:'El sujeto activo del delito de tráfico de influencias penado en el artículo 428 del Código penal:', o:{a:'Ha de tener la condición de autoridad o funcionario público.',b:'Puede ser autoridad, funcionario público, o un particular.',c:'Sólo puede ser un particular.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'Art.428 CP: el sujeto activo del tráfico de influencias del art.428 debe ser autoridad o funcionario público que influye en otro funcionario.'}},
{n:75, q:'El sujeto activo del delito de tráfico de influencias penado en el artículo 429 del Código penal:', o:{a:'Ha de tener la condición de autoridad o funcionario público.',b:'Puede ser autoridad, funcionario público, o un particular.',c:'Sólo puede ser un particular.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'Art.429 CP: en el tráfico de influencias del art.429, el sujeto activo puede ser autoridad, funcionario público o un particular.'}},
{n:76, q:'Los delitos de tráfico de influencias de los artículos 428 y 429 del Código Penal tienen en común:', o:{a:'Que la conducta castigada consiste en influir en un funcionario público o autoridad para conseguir una resolución que le pueda generar, directa o indirectamente, un beneficio económico para quien realiza la influencia, o para un tercero.',b:'Que el sujeto activo de estos delitos solo puede ser un funcionario público o autoridad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Arts.428 y 429 CP: ambos delitos tienen en común que la conducta consiste en influir en un funcionario para obtener una resolución que genere beneficio económico (a). El sujeto activo difiere: art.428 solo funcionarios, art.429 cualquiera.'}},
{n:77, q:'Los delitos de tráfico de influencias de los artículos 428 y 429 del Código Penal se diferencian en:', o:{a:'Que el delito del artículo 428 tiene señalada pena de prisión de mayor gravedad que la del delito del artículo 429.',b:'Que el delito del artículo 428 tiene señalada pena de multa de mayor gravedad que la del delito del artículo 429.',c:'Que el delito del artículo 428 se castiga con la pena de inhabilitación especial y el del artículo 429 no se castiga con ésta pena.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'Arts.428 y 429 CP: se diferencian en que el art.428 (funcionario que influye) tiene pena de prisión más grave (1-3 años) que el art.429 (particular que influye) (6 meses-1 año).'}},
{n:78, q:'Si se obtuviere el beneficio perseguido, las penas se impondrán en su mitad superior:', o:{a:'En el delito de tráfico de influencias del artículo 428 del Código Penal.',b:'En el delito de tráfico de influencias del artículo 429 del Código Penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Arts.428 y 429 CP: en ambos delitos de tráfico de influencias, si se obtiene el beneficio perseguido, las penas se imponen en su mitad superior.'}},
{n:79, q:'Comete delito de tráfico de influencias:', o:{a:'La autoridad o funcionario que influye en otra autoridad o funcionario prevaliéndose de su cargo para conseguir una resolución que le pueda generar un beneficio económico.',b:'El particular que influye en un funcionario público o autoridad, prevaliéndose de cualquier situación derivada de su relación personal con éstos, para conseguir una resolución que le pueda generar un beneficio económico.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas'}, correct:'c', why:{c:'Art.428 CP: el funcionario que influye prevaliéndose de su cargo (a) y el art.429 CP: el particular que influye prevaliéndose de relaciones personales (b) cometen delito de tráfico de influencias.'}},
{n:80, q:'En el artículo 430 del Código Penal:', o:{a:'Se castiga a quienes se ofrecieren a llevar a cabo actividades relacionadas con el tráfico de influencias.',b:'Se castiga el hecho de solicitar por su actividad dádivas, presentes o cualquier otra remuneración, o el hecho de aceptar ofrecimiento o promesa.',c:'Solo pueden ser autores del delito tipificado en este artículo las autoridades o funcionarios públicos.',d:'Las respuestas a y b son correctas.'}, correct:'d', why:{d:'Art.430 CP: se castiga tanto ofrecer llevar a cabo actividades de tráfico de influencias (a) como solicitar dádivas por ello o aceptar ofrecimiento (b). El sujeto activo puede ser cualquier persona.'}},
{n:81, q:'Con respecto al delito de tráfico de influencias del artículo 430 del Código Penal, indique la respuesta incorrecta:', o:{a:'Cuando el delito fuere cometido por un particular se impondrá la pena de prisión de 6 meses a 1 año.',b:'Cuando el delito fuere cometido por autoridad o funcionario público, además de la pena de prisión, se le impondrá la de inhabilitación especial para empleo o cargo público y para el ejercicio del derecho de sufragio pasivo por tiempo de 1 a 4 años.',c:'Cuando una persona jurídica sea responsable de los delitos de tráfico de influencias tipificados en los artículos 428, 429 y 430 del Código Penal se le impondrá la pena de multa de 6 meses a 2 años.',d:'Se impondrán las penas respectivamente previstas en su mitad superior, cuando el valor del perjuicio causado excediere de 250.000 euros.'}, correct:'a', why:{a:'La opción a es incorrecta: cuando el delito del art.430 CP lo comete un particular, la pena es de prisión de 6 meses a 1 año O multa de 12 a 24 meses (no solo prisión).'}},
{n:82, q:'Juan, alto cargo de un Ministerio, se ofrece a Felipe para influir ante un integrante de la Comisión Interministerial de Armas y Explosivos con el fin de que Felipe obtenga la homologación de un nuevo tipo de cartucho para armas cortas. A cambio de esta gestión Juan solicita a Felipe la cantidad de diez mil euros. A Felipe no le interesa esta mediación y rehúsa entregar dicha cantidad a Juan. Teniendo en cuenta lo descrito, indique la respuesta correcta:', o:{a:'Juan no comete delito alguno.',b:'La conducta de Juan podría ser constitutiva de un delito de Tráfico de influencias del artículo 428 del Código Penal.',c:'La conducta de Juan podría ser constitutiva de un delito de Tráfico de influencias del artículo 429 del Código Penal.',d:'La conducta de Juan podría ser constitutiva de un delito de Tráfico de influencias del artículo 430 del Código Penal.'}, correct:'d', why:{d:'Art.430 CP: Juan se ofrece a llevar a cabo actividades de tráfico de influencias (aunque Felipe no acceda), lo que encaja en el tipo del art.430 CP (ofrecer llevar a cabo actividades de influencias).'}},
{n:83, q:'Dispone el artículo 431 del Código Penal que, a los efectos de lo dispuesto en los delitos de tráfico de influencias, se entenderán funcionarios públicos:', o:{a:'Los determinados en el artículo 24 del Código Penal.',b:'Los determinados en el artículo 427 del Código Penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.431 CP: a efectos de los delitos de tráfico de influencias, se consideran funcionarios públicos tanto los del art.24 CP (a) como los del art.427 CP (b).'}},
{n:84, q:'Dispone el artículo 431 del Código Penal, en relación con el artículo 24 del mismo Código, que a los efectos de lo dispuesto en los delitos de tráfico de influencias, se entenderán funcionarios públicos:', o:{a:'A quienes por disposición inmediata de la ley participen del ejercicio de funciones públicas.',b:'A quienes por nombramiento de la autoridad competente participen del ejercicio de funciones públicas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.24 CP: son funcionarios públicos quienes participan del ejercicio de funciones públicas por disposición legal (a) o por nombramiento de autoridad competente (b).'}},
{n:85, q:'Dispone el artículo 431 del Código Penal, en relación con el artículo 24 del mismo Código, que a los efectos de lo dispuesto en los delitos de tráfico de influencias, se entenderán funcionarios públicos:', o:{a:'A los particulares que presten sus servicios en el ámbito de las empresas o sociedades de gestión estratégica.',b:'A quienes por disposición de la autoridad competente participen del ejercicio de funciones públicas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.24 CP: también son funcionarios públicos quienes participan del ejercicio de funciones públicas por disposición de la autoridad competente (b). Los particulares en empresas privadas (a) no.'}},
{n:86, q:'Dispone el artículo 431 del Código Penal, en relación con el artículo 427 del mismo Código, que a los efectos de lo dispuesto en los delitos de tráfico de influencias, se entenderá/n funcionario/s público:', o:{a:'Cualquier persona que ostente un cargo o empleo legislativo, administrativo o judicial de un país de la Unión Europea o de cualquier otro país extranjero, tanto por nombramiento como por elección.',b:'Notarios y registradores de la propiedad que hayan manifestado su deseo de acogerse a la fe pública administrativa.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.431 en relación con art.427 CP: se considera funcionario público a quien ostenta cargo legislativo, administrativo o judicial en la UE o cualquier país extranjero (a).'}},
{n:87, q:'Dispone el artículo 431 del Código Penal, en relación con el artículo 427 del mismo Código, que a los efectos de lo dispuesto en los delitos de tráfico de influencias, se entenderá funcionario público:', o:{a:'Cualquier funcionario o agente de la Unión Europea o de una organización internacional pública.',b:'Cualquier persona a la que se haya asignado y que esté ejerciendo una función de servicio público que consista en la gestión, en los Estados miembros o en terceros países, de intereses financieros de la Unión Europea o en tomar decisiones sobre esos intereses.',c:'Cualquier persona que ejerza una función pública para un país de la Unión Europea o cualquier otro país extranjero, incluido un organismo público o una empresa pública, para la Unión Europea o para otra organización internacional pública.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.427 CP en relación con art.431: todas las categorías mencionadas se consideran funcionarios públicos a efectos del tráfico de influencias.'}},
{n:88, q:'Con respecto al delito de malversación del artículo 432 del Código Penal, indique la respuesta incorrecta:', o:{a:'Sujeto activo de este delito solo puede serlo autoridad o funcionario público.',b:'Este delito se puede cometer dolosamente o por imprudencia.',c:'La conducta punible consiste en apropiarse del patrimonio público que tenga a su cargo por razón de sus funciones o con ocasión de las mismas.',d:'También es punible consentir que un tercero se apropie de dicho patrimonio.'}, correct:'b', why:{b:'La opción b es incorrecta: el delito de malversación del art.432 CP es un delito doloso; la modalidad imprudente es la del art.432.3 CP que prevé una pena atenuada para la distracción por imprudencia grave.'}},
{n:89, q:'En el delito de malversación del artículo 432.1 del Código Penal, la pena a imponer es de...', o:{a:'Prisión de 2 a 6 años.',b:'Inhabilitación especial para empleo o cargo público y para el derecho de sufragio pasivo por un tiempo de 6 a 10 años.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.432.1 CP: la malversación básica se castiga con prisión de 2 a 6 años (a) e inhabilitación especial para empleo/cargo público y sufragio pasivo de 6 a 10 años (b).'}},
{n:90, q:'En el delito de malversación del artículo 432.2 del Código Penal, se produce una agravación de las penas previstas en el apartado primero de este precepto, cuando...', o:{a:'El valor del patrimonio público apropiado o malversado excede de 250.000 euros.',b:'Se hubiera causado un daño o entorpecimiento grave al servicio público.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.432.2 CP: la agravación se produce cuando el valor excede de 250.000 euros (a) o se causa daño grave al servicio público (b).'}},
{n:91, q:'En el delito de malversación del artículo 432.2 del Código Penal, se produce una agravación de las penas previstas en el apartado primero de este precepto, cuando...', o:{a:'El valor del perjuicio causado excediere de 50.000 euros.',b:'El valor del patrimonio apropiado excediere de 50.000 euros.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'Art.432.2 CP: la agravación se produce cuando excede de 250.000 euros (no 50.000), por lo que las opciones a y b son incorrectas.'}},
{n:92, q:'En el delito de malversación del artículo 432.2 del Código Penal, se produce una agravación de las penas previstas en el apartado primero de este precepto, cuando...', o:{a:'Las cosas malversadas fueran de valor artístico.',b:'Se dejare intencionadamente de reclamar lo defraudado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'Art.432.2 CP: el valor artístico de las cosas (a) y no reclamar lo defraudado (b) no son circunstancias de agravación del art.432.2; las agravaciones son el valor superior a 250.000€ y el daño grave al servicio.'}},
{n:93, q:'En el delito de malversación del artículo 432.2 del Código Penal, se produce una agravación de las penas previstas en el apartado primero de este precepto, cuando...', o:{a:'Las cosas malversadas fueran de valor científico.',b:'Se tratare de efectos destinados a aliviar alguna calamidad pública.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'Art.432.2 CP: el valor científico y los efectos para calamidades públicas no son circunstancias del art.432.2; corresponden a otras agravaciones del CP.'}},
{n:94, q:'Con respecto a las penas aplicables al delito de malversación del artículo 432.2 del Código Penal, indique la respuesta correcta.', o:{a:'Multa de 1 a 3 años.',b:'Prisión de 4 a 8 años.',c:'Inhabilitación especial de 10 a 20 años.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.432.2 CP: las penas agravadas son multa de 1 a 3 años (a), prisión de 4 a 8 años (b) e inhabilitación especial de 10 a 20 años (c).'}},
{n:95, q:'En lo que respecta al delito de malversación, de conformidad con lo dispuesto en el artículo 432.2 del Código Penal, si el valor del perjuicio causado o del patrimonio público apropiado excediere de 250.000 euros, se impondrá la pena de...', o:{a:'Pena de prisión de 4 a 8 años, en su mitad superior, pudiéndose llegar hasta la superior en grado.',b:'Pena superior en grado a la de prisión de 4 a 8 años.',c:'Pena superior en grado a la de prisión de 4 a 8 años, pudiéndose llegar hasta la superior en dos grados, razonándolo debidamente en la sentencia.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'Art.432.2 CP: cuando el valor excede de 250.000 euros se impone la pena en su mitad superior, pudiendo llegar hasta la superior en grado.'}},
{n:96, q:'En lo que respecta al delito de malversación del artículo 432.2 del Código Penal, si el perjuicio causado o el valor de patrimonio público es inferior a cuatro mil euros, se imponen las penas de ...', o:{a:'Prisión de uno a dos años y multa de seis meses y un día a doce meses, y en todo caso inhabilitación especial para cargo o empleo público y derecho de sufragio pasivo por tiempo de uno a cuatro años.',b:'Prisión de uno a dos años y multa de tres meses y un día a doce meses, y en todo caso inhabilitación especial para cargo o empleo público y derecho de sufragio pasivo por tiempo de uno a cuatro años.',c:'Prisión de uno a dos años o multa de tres meses y un día a doce meses, y en todo caso inhabilitación especial para cargo o empleo público y derecho de sufragio pasivo por tiempo de uno a cuatro años.',d:'Prisión de uno a dos años y multa de seis meses y un día a doce meses, y en todo caso inhabilitación especial para cargo o empleo público y derecho de sufragio pasivo por tiempo de uno a cinco años.'}, correct:'a', why:{a:'Art.432.3 CP: cuando el perjuicio es inferior a 4.000 euros, la pena es prisión de 1-2 años y multa de 6 meses y 1 día a 12 meses, y en todo caso inhabilitación especial de 1 a 4 años.'}},
{n:97, q:'En lo que respecta al delito de malversación del artículo 432 bis del Código Penal, indique la respuesta incorrecta.', o:{a:'El sujeto activo debe ser autoridad o funcionario público.',b:'La conducta punible consiste en destinar a usos privados el patrimonio público puesto a su cargo, por razón de sus funciones, o con ocasión de las mismas.',c:'Se castiga con la pena de prisión de 6 meses a 3 años e inhabilitación para empleo o cargo público de 1 a 4 años.',d:'Este delito requiere que el sujeto activo no tenga ánimo de apropiarse del patrimonio público.'}, correct:'d', why:{d:'La opción d es incorrecta en cuanto a "no tenga ánimo de apropiarse"; el art.432 bis castiga la distracción del patrimonio público para usos privados, que precisamente implica un uso indebido aunque no sea apropiación definitiva.'}},
{n:98, q:'En el delito de malversación del artículo 432 bis del Código Penal, si el culpable no reintegrara los mismos elementos del patrimonio distraídos, dentro de los diez días siguientes al de la incoación del proceso...', o:{a:'Se le impondrán las penas previstas en su mitad superior.',b:'Se le impondrá la pena superior en grado.',c:'Será condenado por un delito de apropiación indebida.',d:'Se le impondrán las penas del artículo 432 CP.'}, correct:'d', why:{d:'Art.432 bis CP: si no se reintegra el patrimonio en 10 días, se imponen las penas del art.432 CP (malversación propia), con las mismas consecuencias que la apropiación.'}},
{n:99, q:'Con respecto al delito de malversación del artículo 433 del Código Penal, indique la respuesta correcta...', o:{a:'Sujeto activo de este delito puede ser una autoridad, funcionario público, o un particular.',b:'La conducta punible consiste en dar al patrimonio público que administrare una aplicación pública o privada diferente de aquella a la que estuviere destinado.',c:'Se requiere que la conducta se halle comprendida en los artículos 432 o 432 bis del Código Penal.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'Art.433 CP: la malversación impropia consiste en dar al patrimonio público una aplicación pública diferente de la que le está destinada (b). El sujeto activo solo puede ser autoridad o funcionario, no particulares.'}},
{n:100, q:'El delito de malversación del artículo 433 del Código Penal se castiga con las penas de...', o:{a:'Prisión de uno a cuatro años e inhabilitación absoluta de dos a seis años, si resultare daño o entorpecimiento graves del servicio al que estuviere consignado, y de inhabilitación de empleo o cargo público de uno a tres años y multa de tres a doce meses, si no resultare.',b:'Prisión de uno a cuatro años e inhabilitación especial de empleo o cargo público de dos a seis años, si resultare daño o entorpecimiento graves del servicio al que estuviere consignado, y de inhabilitación de empleo o cargo público de uno a tres años y multa de tres a doce meses, si no resultare.',c:'Prisión de dos a cinco años e inhabilitación especial de empleo o cargo público de dos a seis años, si resultare daño o entorpecimiento graves del servicio al que estuviere consignado, y de inhabilitación de empleo o cargo público de uno a tres años y multa de tres a doce meses, si no resultare.',d:'Prisión de uno a cuatro años e inhabilitación especial de empleo o cargo público de uno a tres años y multa de seis a doce meses, si resultare daño o entorpecimiento graves del servicio al que estuviere consignado, y de inhabilitación de empleo o cargo público de uno a tres años y multa de tres a doce meses, si no resultare.'}, correct:'b', why:{b:'Art.433 CP: si hay daño al servicio → prisión 1-4 años e inhabilitación especial 2-6 años; si no hay daño → inhabilitación especial 1-3 años y multa 3-12 meses.'}},
{n:101, q:'Con respecto al delito de malversación del artículo 433 bis.1 del Código Penal, indique la respuesta incorrecta:', o:{a:'Sujeto activo de este delito solo puede serlo una autoridad o funcionario público.',b:'Se castiga al que falseare la contabilidad de una persona jurídica pública o privada, los documentos que deban reflejar su situación, o la información contenida en los mismos.',c:'Para que exista este delito la conducta debe llevarse a cabo de forma idónea para causar un perjuicio económico a la entidad pública de la que se dependa.',d:'Este delito se castiga con la pena de inhabilitación especial para empleo o cargo público por tiempo de 1 a 10 años y multa de 12 a 24 meses.'}, correct:'a', why:{a:'La opción a es incorrecta: el art.433 bis CP puede ser cometido por cualquier persona que tenga obligación de reflejar la situación de la entidad, no solo funcionarios. El sujeto activo puede ser más amplio.'}},
{n:102, q:'Con respecto al delito de malversación del artículo 433 bis.2 del Código Penal, indique la respuesta correcta:', o:{a:'Sujeto activo de este delito solo puede ser autoridad o funcionario público.',b:'La conducta delictiva consiste en facilitar a terceros información mendaz relativa a la entidad pública de la que dependa.',c:'Para que exista delito, la información facilitada debe ser idónea para causar un perjuicio económico a la entidad pública de la que dependa.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.433 bis.2 CP: sujeto activo es autoridad o funcionario (a), la conducta es facilitar información mendaz (b) y requiere que sea idónea para causar perjuicio económico (c).'}},
{n:103, q:'En el delito de malversación del artículo 433 bis del Código Penal, si se llegare a causar el perjuicio económico a la entidad, se impondrán las penas de...', o:{a:'Prisión de dos a cuatro años, inhabilitación especial para empleo o cargo público por tiempo de tres a diez años y multa de doce a veinticuatro meses.',b:'Prisión de uno a cuatro años, inhabilitación especial para empleo o cargo público por tiempo de tres a diez años y multa de doce a veinticuatro meses.',c:'Prisión de uno a cuatro años, inhabilitación especial para empleo o cargo público por tiempo de tres a seis años y multa de doce a veinticuatro meses.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Art.433 bis CP: si se causa el perjuicio económico, la pena es prisión de 1-4 años, inhabilitación especial de 3-10 años y multa de 12-24 meses.'}},
{n:104, q:'El artículo 433 Ter del Código Penal dice que, a efectos de este Código se entenderá por patrimonio público...', o:{a:'Todo el conjunto de bienes y derechos, de contenido económico-patrimonial, pertenecientes a las Administraciones públicas, que se halle debidamente inventariado.',b:'Todo el conjunto de bienes y derechos, de contenido económico-patrimonial, pertenecientes a las Administraciones públicas, salvo lo referido a bienes inmateriales.',c:'Todo el conjunto de bienes y derechos, de contenido económico-patrimonial, pertenecientes a las Administraciones públicas, que se hallen inscritos en los registros correspondientes.',d:'Todo el conjunto de bienes y derechos, de contenido económico-patrimonial, pertenecientes a las Administraciones públicas.'}, correct:'d', why:{d:'Art.433 ter CP: el patrimonio público comprende todo el conjunto de bienes y derechos de contenido económico-patrimonial pertenecientes a las Administraciones públicas, sin limitaciones adicionales de inventario ni registro.'}},
{n:105, q:'Según el artículo 434 del Código Penal, en los delitos de malversación tipificados en los artículos 432, 432 bis, 433 y 433 bis de este Código, se impondrá la pena inferior en uno o dos grados, cuando...', o:{a:'El culpable hubiera reparado, total o parcialmente, el perjuicio causado al patrimonio público antes de ser descubierto por las autoridades.',b:'El culpable hubiera reparado, de modo efectivo e íntegro, el perjuicio causado al patrimonio público antes de ser descubierto por las autoridades.',c:'El culpable hubiera reparado, de modo efectivo e íntegro, el perjuicio causado al patrimonio público antes del inicio del juicio oral.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Art.434 CP: la pena inferior en uno o dos grados se impone cuando el culpable hubiera reparado de modo efectivo e íntegro el perjuicio antes del inicio del juicio oral.'}},
{n:106, q:'Según el artículo 434 del Código Penal, en los delitos de malversación tipificados en los artículos 432, 432 bis, 433, y 433 bis de este Código, se impondrá la pena inferior en uno o dos grados, cuando...', o:{a:'El culpable hubiera colaborado activa y eficazmente con las autoridades o sus agentes para obtener pruebas decisivas para la identificación de los responsables.',b:'El culpable hubiera colaborado activa y eficazmente con las autoridades o sus agentes para obtener pruebas decisivas para la captura de otros responsables.',c:'El culpable hubiera colaborado activa y eficazmente con las autoridades o sus agentes para el completo esclarecimiento de los hechos delictivos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.434 CP: la rebaja procede cuando el culpable colabora para identificar responsables (a), para capturarlos (b) o para el completo esclarecimiento (c).'}},
{n:107, q:'Según el artículo 435 del Código Penal, en los delitos de malversación, las disposiciones contenidas en el capítulo VI, del Título XIX, del Libro Segundo del Código Penal son extensivas a...', o:{a:'Los que se hallen en cualquier concepto de fondos, rentas o efectos de las administraciones públicas o de entidades privadas subvencionadas con fondos públicos.',b:'A los particulares legalmente designados como depositarios de caudales o efectos públicos.',c:'A los administradores o depositarios de dinero o bienes embargados, secuestrados o depositados por una autoridad pública, siempre y cuando no pertenezcan a particulares.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'d', why:{d:'Art.435 CP: las disposiciones de malversación son extensivas a quienes sean depositarios de caudales o efectos públicos (b) y a los administradores de bienes embargados/secuestrados, aunque pertenezcan a particulares (c, que incluye también esos casos). La opción a es demasiado amplia.'}},
{n:108, q:'Según el artículo 435 del Código Penal, en los delitos de malversación, las disposiciones contenidas en el capítulo VI, del Título XIX, del Libro Segundo del Código Penal son extensivas a...', o:{a:'A los administradores concursales, con relación a la masa concursal o los intereses económicos de los acreedores.',b:'A las personas jurídicas que sean responsables de los delitos recogidos en este capítulo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.435.3 CP: las disposiciones de malversación son extensivas a los administradores concursales con relación a la masa concursal (a). Las personas jurídicas (b) no están expresamente en el art.435.'}},
{n:109, q:'-Con respecto al delito de defraudación del artículo 436 del Código Penal, indique la respuesta incorrecta:', o:{a:'Se castiga a la autoridad o funcionario que, interviniendo por razón de su cargo en cualquiera de los actos de las modalidades de contratación pública, usase cualquier artificio para defraudar a cualquier ente público.',b:'Se castiga a la autoridad o funcionario público que interviniendo por razón de su cargo en liquidaciones de efectos o haberes públicos se concertara con los interesados para defraudar a cualquier ente público.',c:'Se castiga al particular que se haya concertado con autoridad o funcionario público acceder a documentos o efectos que la autoridad haya limitado o restringido en función de su contenido.',d:'Se castiga al particular que se haya concertado con autoridad o funcionario público para defraudar a cualquier ente público.'}, correct:'c', why:{c:'La opción c es incorrecta: el art.436 CP no castiga acceder a documentos limitados; castiga al particular que se concierta con funcionario para defraudar a un ente público.'}},
{n:110, q:'Con respecto al delito de defraudación del artículo 436 del Código Penal, indique la respuesta correcta:', o:{a:'Sujeto activo de este delito solo pueden serlo las autoridades o funcionarios públicos.',b:'Se castiga a quienes, interviniendo por razón de su cargo, en cualesquiera de los actos de las modalidades de contratación pública, se concertaren con los interesados para defraudar a cualquier ente público.',c:'Si el autor lograre su propósito se castigará el hecho con las penas superiores en grado a las respectivamente previstas.',d:'Se impondrán las penas respectivamente previstas en su mitad superior cuando el valor de lo defraudado excediere de 50.000 euros.'}, correct:'b', why:{b:'Art.436 CP: se castiga a quienes interviniendo en contratación pública se conciertan con los interesados para defraudar (b). El sujeto activo puede ser autoridad, funcionario o particular que se concierte con ellos.'}},
{n:111, q:'El delito de defraudación del artículo 436 del Código Penal...', o:{a:'Se castiga con las penas de prisión de 2 a 6 años e inhabilitación especial para empleo o cargo público y para el ejercicio del derecho de sufragio pasivo por tiempo de 5 a 10 años, cuando el sujeto activo fuere autoridad o funcionario.',b:'Se castiga con la pena de prisión de 2 a 6 años e inhabilitación para obtener subvenciones y ayudas públicas, para contratar con entes, organismos o entidades que formen parte del sector público, y para gozar de beneficios o incentivos fiscales y de la seguridad social por un tiempo de 2 a 7 años, cuando el sujeto activo fuere un particular.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.436 CP: cuando es autoridad/funcionario la pena incluye inhabilitación para empleo/cargo y sufragio pasivo (a); cuando es particular incluye inhabilitación para subvenciones y contratar con el sector público (b).'}},
{n:112, q:'Un funcionario del Ayuntamiento encargado de las fotocopiadoras que se concierta con la empresa encargada de repararlas para que facture en exceso y repartirse con ésta la diferencia de lo facturado, comete un delito de:', o:{a:'Cohecho del artículo 423 del CP.',b:'Defraudación del artículo 436 del CP.',c:'Exacción ilegal del artículo 437 del CP.',d:'Malversación del artículo 432 del CP.'}, correct:'b', why:{b:'El funcionario se concierta con interesados (empresa) en actos de contratación pública para defraudar al ente público, lo que encaja en el art.436 CP (defraudación en contratación pública).'}},
{n:113, q:'Con respecto al delito de exacciones ilegales del artículo 437 del Código Penal, indique la respuesta incorrecta:', o:{a:'Sujeto activo de este delito solo pueden serlo las autoridades o funcionarios públicos.',b:'Se castiga a quienes destinaren a usos ajenos a la función pública los caudales o efectos puestos a su cargo por razón de sus funciones.',c:'Se castiga a quienes exigieren, directa o indirectamente derechos, tarifas por aranceles, o minutas en cuantía mayor a la legalmente señalada.',d:'Se castiga a quienes exigieren derechos, tarifas por aranceles, o minutas que no sean debidos.'}, correct:'b', why:{b:'La opción b describe la conducta del art.432 bis CP (distracción de patrimonio público), no las exacciones ilegales del art.437 CP, que consisten en exigir derechos o tarifas indebidas o superiores a las legales.'}},
{n:114, q:'Con respecto al delito de exacciones ilegales del artículo 437 del Código Penal, indique la respuesta incorrecta:', o:{a:'Las penas a imponer lo son sin perjuicio de los reintegros a que se viniere obligado.',b:'Se castiga a quienes exigieren, directa o indirectamente derechos, tarifas por aranceles, o minutas en cuantía mayor a la legalmente señalada.',c:'Se castiga a quienes exigieren derechos, tarifas por aranceles, o minutas que no sean debidos.',d:'Las penas a imponer son la de multa 6 a 24 meses o suspensión de empleo o cargo público por tiempo de 6 meses a 4 años.'}, correct:'d', why:{d:'La opción d es incorrecta: la pena del art.437 CP es multa de 6 a 24 meses Y suspensión de empleo o cargo público de 6 meses a 4 años (es conjuntiva, no alternativa).'}},
{n:115, q:'El artículo 438 del Código Penal establece que cuando una autoridad o funcionario público, abusando de su cargo, cometiere algún delito de estafa o de fraude de prestaciones del Sistema de Seguridad Social del artículo 307 ter del Código Penal...', o:{a:'Será castigado con las penas respectivamente señaladas, en su mitad superior, y con la de inhabilitación absoluta por tiempo de 5 a 10 años.',b:'Será castigado con las penas respectivamente señaladas y con la de inhabilitación especial para empleo o cargo público por tiempo de 5 a 10 años.',c:'Será castigado con las penas respectivamente señaladas, en su mitad superior, pudiéndose llegar hasta la superior en grado, y con la de inhabilitación especial para empleo o cargo público y para el ejercicio del derecho de sufragio pasivo por tiempo de 5 a 10 años, salvo que los hechos estén castigados con pena más grave en otro precepto de éste Código.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Art.438 CP: la estafa o fraude de prestaciones SS cometido por funcionario abusando del cargo se castiga con penas en mitad superior (pudiendo llegar a superior en grado) e inhabilitación especial 5-10 años.'}},
{n:116, q:'Los culpables de un delito de exacciones ilegales del artículo 437 del Código Penal serán castigados con las penas de:', o:{a:'Multa de 6 a 24 meses y suspensión de empleo o cargo público de 6 meses a 4 años.',b:'Multa de 6 a 24 meses y suspensión de empleo o cargo público de 12 meses a 2 años.',c:'Multa de 6 a 18 meses y suspensión de empleo o cargo público de 18 meses a 4 años.',d:'Multa de 6 a 18 meses y suspensión de empleo o cargo público de 12 meses a 4 años.'}, correct:'a', why:{a:'Art.437 CP: las exacciones ilegales se castigan con multa de 6 a 24 meses y suspensión de empleo o cargo público de 6 meses a 4 años.'}},
{n:117, q:'Con respecto al delito de defraudación tipificado en el artículo 438 bis del Código Penal, indique la respuesta correcta.', o:{a:'Sujeto activo de este delito puede ser cualquier autoridad o funcionario público.',b:'La conducta punible consiste en haber obtenido un incremento patrimonial o una cancelación de obligaciones o deudas por un valor superior a 250.000 euros respecto a sus ingresos acreditados, y negarse abiertamente a dar el debido cumplimiento a los requerimientos de los órganos competentes destinados a comprobar su justificación.',c:'El incremento patrimonial o cancelación de deudas u obligaciones debe haberse producido durante el desempeño de su función o cargo y hasta dos años después de haber cesado en ellos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.438 bis CP: el enriquecimiento ilícito puede ser cometido por cualquier autoridad o funcionario (a), requiere incremento superior a 250.000 euros con negativa a justificarlo (b) y debe producirse durante o hasta dos años después del ejercicio del cargo (c).'}},
{n:118, q:'El delito de defraudación tipificado en el artículo 438 bis del Código Penal, se castiga con las penas de...', o:{a:'Prisión de seis meses a tres años, multa del tanto al triplo del beneficio obtenido, e inhabilitación especial para empleo o cargo público y para el ejercicio del derecho de sufragio pasivo por tiempo de dos a siete años.',b:'Prisión de uno a tres años, multa del tanto al triplo del beneficio obtenido, e inhabilitación especial para empleo o cargo público y para el ejercicio del derecho de sufragio pasivo por tiempo de dos a siete años.',c:'Prisión de seis meses a dos años, multa del tanto al triplo del beneficio obtenido, e inhabilitación especial para empleo o cargo público y para el ejercicio del derecho de sufragio pasivo por tiempo de dos a siete años.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Art.438 bis CP: el enriquecimiento ilícito se castiga con prisión de 6 meses a 3 años, multa del tanto al triple e inhabilitación especial de 2 a 7 años.'}},
{n:119, q:'Con respecto al delito de negociaciones prohibidas a funcionarios públicos del artículo 439 del Código Penal, la respuesta incorrecta.', o:{a:'Se castiga a quien debiendo intervenir por razón de su cargo en cualquier clase de contrato, asunto, operación o actividad se aproveche de tal circunstancia para forzar cualquier forma de participación en tales negocios o actuaciones.',b:'Se castiga a quien realiza el hecho directamente como a quien lo hace por medio de persona interpuesta.',c:'Este delito está castigado con las penas de prisión de 6 meses a 2 años, multa de 12 a 24 meses e inhabilitación especial para empleo o cargo público y para el ejercicio del derecho de sufragio pasivo por un tiempo de 2 a 7 años.',d:'Si resultare grave daño para tercero o causa pública se impondrán las penas previstas en su mitad superior.'}, correct:'c', why:{c:'La opción c es incorrecta: la pena del art.439 CP no incluye sufragio pasivo en esos términos; la pena es prisión de 6 meses a 2 años, multa de 12 a 24 meses e inhabilitación especial de 2 a 7 años (sin mención específica al sufragio).'}},
{n:120, q:'En el delito de negociaciones prohibidas a funcionarios públicos del art. 439 del Código Penal:', o:{a:'Se castiga el hecho de no informar a los superiores jerárquicos sobre cualquier contrato o actividad privada que desarrolle el funcionario.',b:'Se castiga el hecho de participar en negocios o actuaciones, sobre las que el funcionario o autoridad deba intervenir por razón del cargo, aprovechándose de ello.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.439 CP: se castiga participar en negocios en los que el funcionario debe intervenir por su cargo, aprovechándose de ello (b). No hay obligación de informar al superior (a).'}},
{n:121, q:'Con respecto al delito de negociaciones/actividades prohibidas a funcionarios públicos del artículo 440 del Código Penal, indique la respuesta correcta.', o:{a:'Cometen este delito los peritos, árbitros y contadores partidores que se aprovecharen de su cargo para forzar o facilitarse cualquier forma de participación con respecto de los bienes o cosas en cuya tasación, partición o adjudicación hubieran intervenido.',b:'Cometen este delito los tutores, curadores o albaceas que se aprovecharen de su cargo para forzar o facilitarse cualquier forma de participación con respecto de los bienes pertenecientes a sus pupilos o testamentarías.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.440 CP: tanto los peritos/árbitros/contadores (a) como los tutores/curadores/albaceas (b) que se aprovechan de su cargo para participar en bienes bajo su gestión cometen este delito.'}},
{n:122, q:'Con respecto al delito de negociaciones/actividades prohibidas a funcionarios públicos del artículo 440 del Código Penal, indique la respuesta correcta.', o:{a:'Cometen este delito los administradores concursales que se aprovecharen de su cargo para forzar o facilitarse cualquier forma de participación con respecto de los bienes y derechos integrados en la masa del concurso.',b:'Cometen este delito los que interviniendo por razón de su cargo en liquidaciones de efectos o haberes públicos se concertaren con los interesados para defraudar a cualquier ente público.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.440 CP: los administradores concursales que se aprovechan de su cargo para participar en la masa del concurso cometen este delito (a). La conducta de la b corresponde al art.436 CP.'}},
{n:123, q:'Con respecto al delito de negociaciones/actividades prohibidas a funcionarios públicos del artículo 441 del Código Penal, indique la respuesta correcta.', o:{a:'Sujeto activo de este delito solo pueden serlo los funcionarios públicos y autoridades.',b:'Se castiga a quienes, fuera de los casos permitidos por las leyes o reglamentos, realizaren una actividad profesional, bajo la dependencia o al servicio de entidades privadas o de particulares, en asuntos en que deban intervenir o hayan intervenido por razón de su cargo.',c:'Se castiga a quienes, fuera de los casos permitidos por las leyes o reglamentos, realizaren una actividad de asesoramiento, bajo la dependencia o al servicio de entidades privadas o de particulares, en asuntos que se tramiten, informen o resuelvan en la oficina o centro directivo en que estuvieren destinados o de los que dependan.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.441 CP: el sujeto activo son autoridades y funcionarios (a), se castiga la actividad profesional en asuntos donde intervinieron (b) y la actividad de asesoramiento en asuntos de su dependencia (c).'}},
{n:124, q:'Con respecto al delito de negociaciones/actividades prohibidas a funcionarios públicos del artículo 441 del Código Penal, indique la respuesta incorrecta.', o:{a:'Este delito se castiga con las penas de multa y suspensión de empleo o cargo público.',b:'La actividad profesional o de asesoramiento se castiga también cuando se lleva a cabo a través de persona interpuesta.',c:'La actividad profesional o de asesoramiento se castiga también cuando se realiza de manera accidental.',d:'Si se produjere perjuicio para tercero o causa pública se imponen las penas previstas en su mitad superior.'}, correct:'c', why:{c:'La opción c es incorrecta: el art.441 CP castiga la actividad profesional o de asesoramiento realizada de forma sistemática o continuada, no cuando es meramente accidental.'}},
{n:125, q:'El artículo 441 del Código Penal castiga a la autoridad o funcionario público que, fuera de los casos admitidos en las leyes o reglamentos, realizare por sí o por persona interpuesta, una actividad profesional o de asesoramiento, bajo la dependencia o al servicio de entidades privadas o de particulares:', o:{a:'En asunto en que deba intervenir por razón de su cargo.',b:'En asunto en que haya intervenido por razón de su cargo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'Art.441 CP: el delito se comete en asuntos que se tramiten, informen o resuelvan en su oficina o de los que dependan, lo cual es más amplio que solo donde intervenga o haya intervenido directamente.'}},
{n:126, q:'En el delito de actividades profesionales prohibidas a funcionarios públicos del art. 441 del Código Penal, las conductas previstas solo son punibles:', o:{a:'Si se realizan fuera de los casos admitidos en las leyes o reglamentos.',b:'Si hubiere grave perjuicio para tercero o causa pública.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.441 CP: las conductas solo son punibles si se realizan fuera de los casos admitidos por leyes o reglamentos (a). No se requiere que haya perjuicio como elemento del tipo básico.'}},
{n:127, q:'Con respecto al delito de negociaciones/actividades prohibidas a funcionarios públicos del artículo 442 del Código Penal, indique la respuesta correcta:', o:{a:'Se castiga a quienes hagan uso de un secreto del que tengan conocimiento, por razón de su oficio o cargo, con ánimo de obtener un beneficio económico.',b:'Se castiga a quienes, fuera de los casos permitidos por las leyes o reglamentos, realizaran una actividad profesional, bajo la dependencia o al servicio de entidades privadas o de particulares, en asuntos que se tramiten, informen o resuelvan en la oficina o centro directivo en que estuvieren destinados o de los que dependan.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.442 CP: se castiga el uso de secreto conocido por razón del cargo con ánimo de obtener beneficio económico (a). La conducta de b corresponde al art.441 CP.'}},
{n:128, q:'Con respecto al delito de negociaciones/actividades prohibidas a funcionarios públicos del artículo 442 del Código Penal, indique la respuesta correcta:', o:{a:'Se castiga a quienes, fuera de los casos permitidos por las leyes o reglamentos, realizaran una actividad profesional, bajo la dependencia o al servicio de entidades privadas o de particulares, en asuntos en que deban intervenir o hayan intervenido por razón de su cargo.',b:'Se castiga a quienes hagan uso de una información privilegiada con ánimo de obtener un beneficio económico.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.442 CP: también se castiga el uso de información privilegiada con ánimo de obtener beneficio económico (b). La conducta de a corresponde al art.441 CP.'}},
{n:129, q:'Con respecto al delito de negociaciones/actividades prohibidas a funcionarios públicos del artículo 442 del Código Penal, indique la respuesta incorrecta:', o:{a:'Sujeto activo de este delito solo pueden serlo las autoridades o funcionarios públicos.',b:'Existe delito tanto si el beneficio que se pretende obtener es para quien realiza la acción como si dicho beneficio es para un tercero.',c:'Si resultare grave daño para la causa pública o para un tercero se imponen las penas de prisión de 1 a 6 años e inhabilitación especial de 9 a 12 años.',d:'Cuando no se obtuviere el beneficio perseguido se impondrá la pena inferior en grado.'}, correct:'c', why:{c:'La opción c es incorrecta: la pena agravada del art.442 CP cuando resulta grave daño es diferente de la descrita; es inhabilitación especial con otros tramos.'}},
{n:130, q:'En el delito de negociaciones/actividades prohibidas a funcionarios públicos del artículo 442 del Código Penal se imponen las penas previstas en su mitad superior cuando:', o:{a:'Resultare grave daño para causa pública o para tercero.',b:'Se obtuviere el beneficio perseguido.',c:'El beneficio obtenido supere los 4000 euros.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Art.442 CP: las penas se imponen en su mitad superior cuando se obtiene el beneficio perseguido (b).'}},
{n:131, q:'Para que sea punible el uso de información privilegiada del artículo 442 del Código Penal es preciso.', o:{a:'Que la autoridad o funcionario que hace uso del secreto haya tenido conocimiento del mismo por razón de su oficio o cargo',b:'Que la autoridad o funcionario actúe con ánimo de obtener un beneficio económico para sí o para un tercero.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.442 CP: se requiere que el conocimiento sea por razón del cargo (a) y que haya ánimo de obtener beneficio económico propio o de tercero (b).'}},
{n:132, q:'A efectos del art.442 del Código penal, se entiende por información privilegiada:', o:{a:'Toda información de carácter concreto que se tenga exclusivamente por razón del oficio o cargo público y que no haya sido notificada.',b:'Toda información de carácter concreto que se tenga exclusivamente por razón del oficio o cargo público y que no haya sido publicada.',c:'Toda información de carácter concreto que se tenga exclusivamente por razón del oficio o cargo público y que no haya sido divulgada.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.442 CP: se entiende por información privilegiada toda información concreta por razón del cargo que no haya sido notificada (a), publicada (b) ni divulgada (c).'}},
{n:133, q:'Se entiende por información privilegiada a los efectos del artículo 442 del Código Penal...', o:{a:'La que tenga carácter concreto, se obtenga exclusivamente por razón del oficio o cargo público y no haya sido notificada, publicada o divulgada.',b:'La que haya sido declarada como tal por las autoridades competentes y en función de los procedimientos establecidos.',c:'La que no pueda obtenerse por medio de ninguna de las fuentes ordinarias de información, ni a través de los medios de comunicación social.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'Art.442 CP: la información privilegiada es la que tiene carácter concreto, se obtiene exclusivamente por razón del cargo y no ha sido notificada, publicada ni divulgada.'}},
{n:134, q:'Con respecto al delito de abuso en el ejercicio de la función pública del artículo 443.1 del Código Penal indique la respuesta correcta:', o:{a:'Sujeto activo de este delito solo pueden serlo las autoridades o funcionarios públicos.',b:'Se castiga la mera solicitud de favores sexuales cuando quien los solicita tenga que resolver, evacuar informe o elevar consulta sobre pretensiones pendientes del solicitado o de su círculo familiar.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.443.1 CP: el sujeto activo son autoridades o funcionarios (a) y se castiga la solicitud de favores sexuales en el contexto descrito (b).'}},
{n:135, q:'El delito de abuso en el ejercicio de la función pública del artículo 443.1 del Código Penal consiste en solicitar sexualmente a una persona con la que el funcionario o autoridad tenga pretensiones pendientes de resolución para con...', o:{a:'Ella misma.',b:'Su cónyuge o persona con la que se halle ligada por análoga relación de afectividad.',c:'Ascendiente, descendiente o hermano de la solicitada.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.443.1 CP: el abuso sexual en el ejercicio de la función se castiga cuando la solicitud se dirige a la propia persona (a), su cónyuge/pareja (b) o familiares (c).'}},
{n:136, q:'El delito de abuso en el ejercicio de la función pública del artículo 443.1 del Código Penal se castiga con las penas de:', o:{a:'Prisión de uno a tres años e inhabilitación absoluta por tiempo de seis a doce años.',b:'Prisión de uno a dos años e inhabilitación absoluta por tiempo de seis a doce años.',c:'Prisión de uno a dos años e inhabilitación absoluta por tiempo de cuatro a doce años.',d:'Prisión de dos a cuatro años e inhabilitación absoluta por tiempo de cuatro a doce años.'}, correct:'b', why:{b:'Art.443.1 CP: el delito de abuso sexual en el ejercicio de la función pública se castiga con prisión de 1 a 2 años e inhabilitación absoluta de 6 a 12 años.'}},
{n:137, q:'Con respecto al delito de abuso en el ejercicio de la función pública del artículo 443.2 del Código Penal, indique la respuesta correcta:', o:{a:'Se castiga a quienes solicitaren sexualmente a una persona sujeta a su guarda.',b:'Sujeto activo de este delito solo pueden serlo los funcionarios de Instituciones Penitenciarias.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.443.2 CP: se castiga la solicitud sexual a persona sujeta a guarda del funcionario (a) y el sujeto activo son los funcionarios penitenciarios (b).'}},
{n:138, q:'Sujetos activos del delito tipificado en el artículo 443.2 del Código Penal, pueden ser:', o:{a:'Funcionarios de los centros de protección o de reforma de menores.',b:'Funcionarios de los centros de internamiento de personas extranjeras.',c:'Funcionarios de cualquier centro de detención o custodia, aunque sea de estancia temporal.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.443.2 CP: son sujetos activos los funcionarios de centros de protección/reforma de menores (a), de internamiento de extranjeros (b) y de cualquier centro de detención o custodia (c).'}},
{n:139, q:'El funcionario de Instituciones Penitenciarias que solicitare sexualmente a una persona sujeta a su guarda, será castigado con la pena de:', o:{a:'Prisión de 1 a 4 años e inhabilitación absoluta de 6 a 12 años.',b:'Prisión de 1 a 4 años e inhabilitación especial de 6 a 12 años.',c:'Prisión de 1 a 4 años e inhabilitación absoluta de 6 a 10 años.',d:'Prisión de 1 a 4 años e inhabilitación especial de 6 a 10 años.'}, correct:'d', why:{d:'Art.443.2 CP: el funcionario penitenciario que solicita sexualmente a persona bajo su guarda se castiga con prisión de 1 a 4 años e inhabilitación especial de 6 a 10 años.'}},
{n:140, q:'En el delito de solicitud de favores de naturaleza sexual del art. 443.1 del Código Penal se exige que el funcionario público o autoridad que actúa como sujeto activo:', o:{a:'Se halle ligado a la víctima de forma estable por análoga relación de afectividad.',b:'Deba resolver las pretensiones de la víctima, evacuar informe al respecto o elevar consulta a su superior.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.443.1 CP: se requiere que el funcionario tenga que resolver, evacuar informe o elevar consulta sobre pretensiones pendientes de la víctima o su entorno (b).'}},
{n:141, q:'Las penas previstas en el artículo 443 del Código Penal...', o:{a:'Se imponen en su mitad superior si la persona solicitada es ascendiente, descendiente, hermano o afín en los mismos grados de la persona que bajo su guarda tuviese bajo su guarda.',b:'Se imponen sin perjuicio de las penas que correspondan por los delitos contra la libertad sexual efectivamente cometidos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.443.3 CP: las penas se imponen en mitad superior cuando la solicitud es a familiar de la persona custodiada (a) y sin perjuicio de las penas por delitos sexuales cometidos (b).'}},
{n:142, q:'En el Código Penal se castiga:', o:{a:'La proposición para cometer delito de cohecho.',b:'La conspiración para cometer delito de malversación.',c:'La proposición para cometer delito de revelación de secretos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.445 CP: la proposición, conspiración y provocación para cometer cualquier delito contra la Administración Pública están castigadas, incluyendo cohecho (a), malversación (b) y revelación de secretos (c).'}},
{n:143, q:'La proposición, provocación y la conspiración para cometer cualquiera de los delitos contra la Administración Pública previstos en el Título XIX, del Libro II, del Código Penal, se castiga:', o:{a:'Con las penas respectivamente previstas en su mitad inferior.',b:'Con las penas inferiores en grado a las respectivamente previstas.',c:'Con la pena inferior en uno o dos grados a la respectivamente prevista en cada caso.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Art.445 CP: la proposición, provocación y conspiración para delitos contra la Administración Pública se castigan con las penas inferiores en grado a las respectivamente previstas.'}},
];
